   */
  /* Print styles */
  @page {
    margin: 0;
  }
  * {
    -webkit-print-color-adjust: exact !important;
    color-adjust: exact !important;
  }
  html,
  body {
    height: 100%;
  }
  main {
    height: 100%;
  }
  #index-buttons {
    display: none;
  }
  .page {
    min-height: 100%;
    max-height: 100%;
    height: 100vh;
    box-sizing: border-box;
    break-inside: avoid;
  }
  .page.page--landscape .page__contents {
    -webkit-transform: rotate(-90deg);
    -ms-transform: rotate(-90deg);
    -o-transform: rotate(-90deg);
    transform: rotate(-90deg);
    transform-origin: left top;
    width: 100vh;
    height: 100vw;
    overflow-x: hidden;
    position: absolute;
    top: 100%;
    left: 0;
    padding: 1cm;
    box-sizing: border-box;
  }
  .page.page--landscape .page__contents:after {
    top: 1cm;
    bottom: 1cm;
  }
  /* Non-printing elements */
  #screen-buttons,
  #screen-meta {
    display: none;
  }
  html {
    font-size: calc(0.57 * (1.5vw + 1vh));
  }
}
@media reader, speech, aural {
  .copyright-attribution {
    display: none;
    visibility: hidden;
  }
}
html {
  font-size: 10pt;
}

/*
Because Safari doesn't support @page, we have to trim the page borders and skip the backgrounds.

And because Safari interprets point sizes differently, we have to pick a smaller base font size.

:`(

*/
html.html--safari .page {
  background-image: none !important;
}

html.html--safari .page .page-number {
  bottom: 0;
  right: 0;
